[CmdletBinding()]param([ValidateSet('All','Publication','Verifier','FinalGate')][string]$Focus='All')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
try{Add-Type -AssemblyName System.Security -ErrorAction Stop}catch{throw 'pkcs_runtime_unavailable'}
$root=Split-Path -Parent (Split-Path -Parent $PSScriptRoot);$manifest=Join-Path $root 'evidence/phase1/security-closure.yaml';$verifier=Join-Path $root 'scripts/verify-phase1-security.ps1';$capture=Join-Path $root 'scripts/add-security-closure-review.ps1'
function Assert($condition,$message){if(!$condition){throw "FAILED: $message"}}
function FileHash($path){$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash([IO.File]::ReadAllBytes($path)))).Replace('-','')}finally{$s.Dispose()}}
function HashText($value){$s=[Security.Cryptography.SHA256]::Create();try{$json=($value|ConvertTo-Json -Depth 20 -Compress)-replace"`r`n","`n";$bytes=[Text.UTF8Encoding]::new($false).GetBytes($json);([BitConverter]::ToString($s.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function HashBytes([byte[]]$bytes){[byte[]]$data=[byte[]]::new(0);if($null-ne$bytes){$data=$bytes};$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash($data,0,$data.Length))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Body($a){[ordered]@{threat_id=[string]$a.threat_id;payload_digest=[string]$a.payload_digest;reviewer_identity=$a.reviewer_identity;review_utc=[string]$a.review_utc;procedure_version=[string]$a.procedure_version;environment_fingerprint=$a.environment_fingerprint;previous_attestation_digest=[string]$a.previous_attestation_digest}}
function ArchiveBody($e){[ordered]@{schema_version=[string]$e.schema_version;threat_id=[string]$e.threat_id;payload_digest=[string]$e.payload_digest;history_entries=@($e.history_entries|%{[ordered]@{attestation_digest=[string]$_.attestation_digest;signature_cms_sha256=[string]$_.signature_cms_sha256}});history_count=[int]$e.history_count;latest_attestation_digest=[string]$e.latest_attestation_digest;reviewer_identity=$e.reviewer_identity;review_utc=[string]$e.review_utc;procedure_version=[string]$e.procedure_version;environment_fingerprint=$e.environment_fingerprint}}
function HistoryEntries($history){@($history|%{$property=$_.PSObject.Properties['signature_cms_base64'];[byte[]]$bytes=if($property-and![string]::IsNullOrWhiteSpace([string]$property.Value)){[Convert]::FromBase64String([string]$property.Value)}else{[byte[]]@()};[ordered]@{attestation_digest=[string]$_.attestation_digest;signature_cms_sha256=HashBytes ([byte[]]$bytes)}})}
function Invoke-Verify($path,[string[]]$extra=@()){$out=[IO.Path]::GetTempFileName();$err=[IO.Path]::GetTempFileName();try{$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$verifier,'-ClosurePath',$path,'-DiagnosticFormat','Json')+$extra;$p=Start-Process powershell -ArgumentList $args -Wait -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err;[pscustomobject]@{Exit=$p.ExitCode;Out=(Get-Content -Raw $out);Err=(Get-Content -Raw $err)}}finally{Remove-Item $out,$err -Force -ErrorAction SilentlyContinue}}
function Invoke-FinalGate($scriptPath){$out=[IO.Path]::GetTempFileName();$err=[IO.Path]::GetTempFileName();try{$args=@('-NoProfile','-ExecutionPolicy','Bypass','-File',$scriptPath,'-CallerMachine','hungdinh-lt','-ServerMachine','LAB-DC01','-SecondaryDcMachine','LAB-DC02','-EndpointMachine','LAB-CLIENT01','-TrustedRootPath',$env:PHASE1_TRUSTED_ROOT_PATH,'-ReviewerPolicyPath',$env:PHASE1_REVIEWER_POLICY_PATH);$p=Start-Process powershell -ArgumentList $args -Wait -PassThru -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err;[pscustomobject]@{Exit=$p.ExitCode;Out=(Get-Content -Raw $out);Err=(Get-Content -Raw $err)}}finally{Remove-Item $out,$err -Force -ErrorAction SilentlyContinue}}
function Mutate([scriptblock]$change){$p=Join-Path $env:TEMP("closure-$([guid]::NewGuid()).json");$c=Get-Content -Raw $manifest|ConvertFrom-Json;&$change $c;[IO.File]::WriteAllText($p,($c|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$p}
function RelativeToRoot([string]$path){$base=[IO.Path]::GetFullPath($root).TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar;$full=[IO.Path]::GetFullPath($path);if(!$full.StartsWith($base,[StringComparison]::OrdinalIgnoreCase)){throw 'test_path_outside_root'};$full.Substring($base.Length)}
function Start-Publisher($path,$threat,$thumbprint,$policyPath,[string[]]$extra=@()){
 $stdin=Join-Path $env:TEMP("publisher-stdin-$([guid]::NewGuid()).txt");$stdout=Join-Path $env:TEMP("publisher-out-$([guid]::NewGuid()).txt");$stderr=Join-Path $env:TEMP("publisher-err-$([guid]::NewGuid()).txt");$exitPath=Join-Path $env:TEMP("publisher-exit-$([guid]::NewGuid()).txt")
 [IO.File]::WriteAllText($stdin,"YES`r`n",[Text.UTF8Encoding]::new($false));$quote={param($value)"'"+([string]$value).Replace("'","''")+"'"};$extraTokens=@();foreach($token in $extra){if(([string]$token).StartsWith('-')){$extraTokens+=[string]$token}else{$extraTokens+=&$quote $token}};$invocation="& '$($capture.Replace("'","''"))' -ClosurePath $(&$quote $path) -ThreatId $(&$quote $threat) -ReviewerPolicyPath $(&$quote $policyPath) -SignerThumbprint $(&$quote $thumbprint) $($extraTokens-join' ')";$command="`$code=0;try{$invocation;if(-not `$?){`$code=1}}catch{[Console]::Error.WriteLine(`$_.Exception.Message);`$code=1}finally{[IO.File]::WriteAllText('$($exitPath.Replace("'","''"))',[string]`$code)};exit `$code";$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command))
 $process=Start-Process powershell -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-EncodedCommand',$encoded) -PassThru -NoNewWindow -RedirectStandardInput $stdin -RedirectStandardOutput $stdout -RedirectStandardError $stderr
 [pscustomobject]@{Process=$process;Input=$stdin;Output=$stdout;Error=$stderr;ExitPath=$exitPath}
}
function Wait-Publisher($publisher,[int]$timeoutSeconds=15){
 if(!$publisher.Process.WaitForExit($timeoutSeconds*1000)){try{$publisher.Process.Kill()}catch{};throw 'FAILED: publisher timed out'};$publisher.Process.WaitForExit();$publisher.Process.Refresh()
 Assert (Test-Path $publisher.ExitPath) 'publisher wrapper captured exit code';[pscustomobject]@{ExitCode=[int](Get-Content -Raw $publisher.ExitPath);Out=(Get-Content -Raw $publisher.Output -ErrorAction SilentlyContinue);Err=(Get-Content -Raw $publisher.Error -ErrorAction SilentlyContinue)}
}
function Remove-Publisher($publisher){Remove-Item $publisher.Input,$publisher.Output,$publisher.Error,$publisher.ExitPath -Force -ErrorAction SilentlyContinue}
function New-PublicationTestCertificate {
 $rsa=[Security.Cryptography.RSA]::Create(2048);$request=[Security.Cryptography.X509Certificates.CertificateRequest]::new('CN=Phase1 Publication Test Reviewer',$rsa,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1)
 $request.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new([Security.Cryptography.X509Certificates.X509KeyUsageFlags]::DigitalSignature,$true));$certificate=$request.CreateSelfSigned([DateTimeOffset]::UtcNow.AddMinutes(-5),[DateTimeOffset]::UtcNow.AddHours(1));$flags=[Security.Cryptography.X509Certificates.X509KeyStorageFlags]::PersistKeySet-bor[Security.Cryptography.X509Certificates.X509KeyStorageFlags]::UserKeySet;$persisted=[Security.Cryptography.X509Certificates.X509Certificate2]::new($certificate.Export([Security.Cryptography.X509Certificates.X509ContentType]::Pfx),$null,$flags)
 $store=[Security.Cryptography.X509Certificates.X509Store]::new('My',[Security.Cryptography.X509Certificates.StoreLocation]::CurrentUser);try{$store.Open([Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite);$store.Add($persisted)}finally{$store.Dispose();$certificate.Dispose();$rsa.Dispose()};$persisted
}
function Remove-PublicationTestCertificate($certificate){$store=[Security.Cryptography.X509Certificates.X509Store]::new('My',[Security.Cryptography.X509Certificates.StoreLocation]::CurrentUser);try{$store.Open([Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite);$store.Remove($certificate)}finally{$store.Dispose();$certificate.Dispose()}}
function New-VerifierTestCertificate([switch]$DigitalSignature,[string]$EkuOid){$rsa=[Security.Cryptography.RSA]::Create(2048);$request=[Security.Cryptography.X509Certificates.CertificateRequest]::new('CN=Phase1 Verifier Test Reviewer',$rsa,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1);if($DigitalSignature){$request.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new([Security.Cryptography.X509Certificates.X509KeyUsageFlags]::DigitalSignature,$true))};if($EkuOid){$oids=[Security.Cryptography.OidCollection]::new();$null=$oids.Add([Security.Cryptography.Oid]::new($EkuOid));$request.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]::new($oids,$true))};$certificate=$request.CreateSelfSigned([DateTimeOffset]::UtcNow.AddMinutes(-5),[DateTimeOffset]::UtcNow.AddHours(1));$rsa.Dispose();$certificate}
function Sign-TestBody($body,$certificate){$bytes=[Text.UTF8Encoding]::new($false).GetBytes((($body|ConvertTo-Json -Depth 20 -Compress)-replace"`r`n","`n"));$cms=[Security.Cryptography.Pkcs.SignedCms]::new([Security.Cryptography.Pkcs.ContentInfo]::new($bytes),$true);$signer=[Security.Cryptography.Pkcs.CmsSigner]::new($certificate);$signer.IncludeOption='EndCertOnly';$cms.ComputeSignature($signer);[Convert]::ToBase64String($cms.Encode())}
function New-VerifierFixture($certificate,[string]$requiredEku){$dir=Join-Path $env:TEMP("verifier-fixture-$([guid]::NewGuid())");New-Item -ItemType Directory -Path $dir|Out-Null;$closurePath=Join-Path $dir 'closure.json';$rootPath=Join-Path $dir 'root.cer';$policyPath=Join-Path $dir 'policy.json';$closure=Get-Content -Raw $manifest|ConvertFrom-Json;$record=$closure.records[0];$attestation=@($record.attestations)[-1];$attestation.reviewer_identity=[pscustomobject]@{kind='independent_verifier';name='verifier-test-reviewer'};$attestation.review_utc=[DateTime]::UtcNow.ToString('o');$attestation.procedure_version='phase1-verifier-test/v1';$attestation.environment_fingerprint=[pscustomobject]@{machine_identity='verifier-test';role='independent_reviewer';domain_network_identity='test.local'};$attestation.attestation_digest=HashText (Body $attestation);$attestation.signature_cms_base64=Sign-TestBody (Body $attestation) $certificate;$history=@($record.attestations);$envelope=[ordered]@{schema_version='phase1-history-envelope/v1';threat_id=[string]$record.threat_id;payload_digest=[string]$record.payload_digest;history_entries=HistoryEntries $history;history_count=$history.Count;latest_attestation_digest=[string]$history[-1].attestation_digest;reviewer_identity=[pscustomobject]@{kind='independent_verifier';name='verifier-test-reviewer'};review_utc=[DateTime]::UtcNow.ToString('o');procedure_version='phase1-verifier-test/v1';environment_fingerprint=[pscustomobject]@{machine_identity='verifier-test';role='independent_reviewer';domain_network_identity='test.local'}};$envelope.envelope_digest=HashText (ArchiveBody $envelope);$envelope.signature_cms_base64=Sign-TestBody (ArchiveBody $envelope) $certificate;$record|Add-Member -NotePropertyName history_envelope -NotePropertyValue ([pscustomobject]$envelope) -Force;[IO.File]::WriteAllText($closurePath,($closure|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllBytes($rootPath,$certificate.Export([Security.Cryptography.X509Certificates.X509ContentType]::Cert));$policy=[ordered]@{schema_version='phase1-reviewer-policy/v1';policy_id='verifier-test';procedure_version='phase1-verifier-test/v1';max_clock_skew_seconds=300;required_eku_oids=@($requiredEku);reviewers=@([ordered]@{identity='verifier-test-reviewer';thumbprint=$certificate.Thumbprint;machine_identity='verifier-test';role='independent_reviewer';domain_network_identity='test.local'})};[IO.File]::WriteAllText($policyPath,($policy|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));[pscustomobject]@{Directory=$dir;Closure=$closurePath;Root=$rootPath;Policy=$policyPath;Threat=[string]$record.threat_id}}

if($Focus-in@('All','Publication')){
 $publicationRoot=Join-Path $env:TEMP("phase1-publication-$([guid]::NewGuid())");New-Item -ItemType Directory -Path $publicationRoot|Out-Null
 $certificate=New-PublicationTestCertificate
 $observedIdentity=[Security.Principal.WindowsIdentity]::GetCurrent().Name
 $policyPath=Join-Path $publicationRoot 'reviewer-policy.json';$policy=[ordered]@{procedure_version='phase1-publication-test/v1';reviewers=@([ordered]@{thumbprint=$certificate.Thumbprint;identity=$observedIdentity;machine_identity=$env:COMPUTERNAME;role='independent_security_reviewer';domain_network_identity='test.local'})};[IO.File]::WriteAllText($policyPath,($policy|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))
 try{
   $threat='T-01-15-03'
   foreach($mismatch in @(
    @{Name='identity';Code='reviewer_identity_mismatch';Identity='LAB\not-the-executing-user';Machine=$env:COMPUTERNAME},
    @{Name='machine';Code='reviewer_machine_mismatch';Identity=$observedIdentity;Machine='LAB-DC99'}
   )){
    $mismatchPath=Join-Path $publicationRoot ("mismatch-$($mismatch.Name).json");Copy-Item $manifest $mismatchPath;$beforeMismatch=FileHash $mismatchPath
    $mismatchPolicyPath=Join-Path $publicationRoot ("mismatch-$($mismatch.Name)-policy.json");$mismatchPolicy=[ordered]@{procedure_version='phase1-publication-test/v1';reviewers=@([ordered]@{thumbprint=$certificate.Thumbprint;identity=$mismatch.Identity;machine_identity=$mismatch.Machine;role='independent_security_reviewer';domain_network_identity='test.local'})};[IO.File]::WriteAllText($mismatchPolicyPath,($mismatchPolicy|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))
    $publisher=Start-Publisher $mismatchPath $threat $certificate.Thumbprint $mismatchPolicyPath;try{$result=Wait-Publisher $publisher;Assert ($result.ExitCode-ne0) "$($mismatch.Name) mismatch is rejected";Assert (($result.Out+$result.Err)-match$mismatch.Code) "$($mismatch.Name) mismatch has stable diagnostic";Assert ((FileHash $mismatchPath)-eq$beforeMismatch) "$($mismatch.Name) mismatch leaves manifest byte-identical";Assert (@(Get-ChildItem $publicationRoot -Filter ".mismatch-$($mismatch.Name).json.*.tmp").Count-eq0) "$($mismatch.Name) mismatch creates no temporary publication file"}finally{Remove-Publisher $publisher}
   }

   $observedPath=Join-Path $publicationRoot 'observed.json';Copy-Item $manifest $observedPath;$observedPublisher=Start-Publisher $observedPath $threat $certificate.Thumbprint $policyPath;try{$observedResult=Wait-Publisher $observedPublisher;Assert ($observedResult.ExitCode-eq0) "observed execution context publishes: $($observedResult.Out) $($observedResult.Err)";$observedClosure=Get-Content -Raw $observedPath|ConvertFrom-Json;$published=@((@($observedClosure.records|Where-Object threat_id -eq $threat))[0].attestations)[-1];Assert ([string]$published.reviewer_identity.name-eq$observedIdentity) 'attestation records observed Windows identity';Assert ([string]$published.environment_fingerprint.machine_identity-eq$env:COMPUTERNAME) 'attestation records observed machine identity'}finally{Remove-Publisher $observedPublisher}
  $driftPath=Join-Path $publicationRoot 'drift.json';Copy-Item $manifest $driftPath;$barrier=Join-Path $publicationRoot 'drift-barrier';New-Item -ItemType File -Path "$barrier.wait"|Out-Null
  $driftPublisher=Start-Publisher $driftPath $threat $certificate.Thumbprint $policyPath @('-PublicationBarrierPath',$barrier)
  try{for($i=0;$i-lt150-and!(Test-Path $barrier);$i++){Start-Sleep -Milliseconds 50};if(!(Test-Path $barrier)){$early=Wait-Publisher $driftPublisher;throw "FAILED: drift publisher acquired publication lock: $($early.Out) $($early.Err)"};$drift=Get-Content -Raw $driftPath|ConvertFrom-Json;(@($drift.records|Where-Object threat_id -eq $threat))[0].mitigation_assertion+=' concurrent mutation';[IO.File]::WriteAllText($driftPath,($drift|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$mutatedHash=FileHash $driftPath;Remove-Item "$barrier.wait" -Force;$driftResult=Wait-Publisher $driftPublisher;Assert ($driftResult.ExitCode-ne0) 'protected-field drift is rejected';Assert (($driftResult.Out+$driftResult.Err)-match"publication_conflict:$threat") 'protected-field drift has stable diagnostic';Assert ((FileHash $driftPath)-eq$mutatedHash) 'rejected drift leaves manifest byte-identical'}finally{Remove-Item "$barrier.wait" -Force -ErrorAction SilentlyContinue;Remove-Publisher $driftPublisher}

  $racePath=Join-Path $publicationRoot 'race.json';Copy-Item $manifest $racePath;$raceInitial=Get-Content -Raw $racePath|ConvertFrom-Json;$raceInitialAttestations=@((@($raceInitial.records|Where-Object threat_id -eq $threat))[0].attestations);$raceInitialPredecessor=[string]$raceInitialAttestations[-1].attestation_digest;$raceBarrier=Join-Path $publicationRoot 'race-barrier';New-Item -ItemType File -Path "$raceBarrier.wait"|Out-Null
  $first=Start-Publisher $racePath $threat $certificate.Thumbprint $policyPath @('-PublicationBarrierPath',$raceBarrier)
  try{for($i=0;$i-lt150-and!(Test-Path $raceBarrier);$i++){Start-Sleep -Milliseconds 50};Assert (Test-Path $raceBarrier) 'first publisher acquired publication lock';$second=Start-Publisher $racePath $threat $certificate.Thumbprint $policyPath;Start-Sleep -Milliseconds 500;Remove-Item "$raceBarrier.wait" -Force;$firstResult=Wait-Publisher $first;$secondResult=Wait-Publisher $second;Assert ($firstResult.ExitCode-eq0) "one concurrent publisher succeeds (exit $($firstResult.ExitCode)): $($firstResult.Out) $($firstResult.Err)";Assert ($secondResult.ExitCode-ne0) 'stale concurrent publisher is rejected';Assert (($secondResult.Out+$secondResult.Err)-match"publication_conflict:$threat") 'stale publisher has stable diagnostic';$race=Get-Content -Raw $racePath|ConvertFrom-Json;$raceAttestations=@((@($race.records|Where-Object threat_id -eq $threat))[0].attestations);Assert ($raceAttestations.Count-eq($raceInitialAttestations.Count+1)) 'exactly one concurrent attestation is published';Assert ([string]$raceAttestations[-1].previous_attestation_digest-eq$raceInitialPredecessor) 'published attestation preserves predecessor chain'}finally{Remove-Item "$raceBarrier.wait" -Force -ErrorAction SilentlyContinue;Remove-Publisher $first;if($second){Remove-Publisher $second}}

  $crashPath=Join-Path $publicationRoot 'crash.json';Copy-Item $manifest $crashPath;$beforeCrash=FileHash $crashPath;$crash=Start-Publisher $crashPath $threat $certificate.Thumbprint $policyPath @('-CrashBeforeReplace');try{$crashResult=Wait-Publisher $crash;Assert ($crashResult.ExitCode-ne0) 'injected pre-replace crash fails';Assert (($crashResult.Out+$crashResult.Err)-match'injected_crash_before_replace') 'injected crash has stable diagnostic';Assert ((FileHash $crashPath)-eq$beforeCrash) 'injected crash preserves original manifest bytes';Assert (@(Get-ChildItem $publicationRoot -Filter '.crash.json.*.tmp').Count-eq0) 'injected crash removes publication temporary files'}finally{Remove-Publisher $crash}
 }finally{Remove-PublicationTestCertificate $certificate;Remove-Item $publicationRoot -Recurse -Force -ErrorAction SilentlyContinue}
}

if($Focus-eq'Publication'){Write-Host 'Phase 1 publication security tests passed.';exit 0}

if($Focus-in@('All','FinalGate')){
 if([string]::IsNullOrWhiteSpace($env:PHASE1_TRUSTED_ROOT_PATH)-or[string]::IsNullOrWhiteSpace($env:PHASE1_REVIEWER_POLICY_PATH)){throw 'phase1_reviewer_trust_setup_missing'};$gateRoot=Join-Path $env:TEMP("phase1-finalgate-$([guid]::NewGuid())");try{New-Item -ItemType Directory -Path $gateRoot|Out-Null;foreach($directory in @('scripts','evidence','config')){Copy-Item (Join-Path $root $directory) (Join-Path $gateRoot $directory) -Recurse};New-Item -ItemType Directory -Path (Join-Path $gateRoot 'tests/windows') -Force|Out-Null;Copy-Item (Join-Path $root 'tests/windows/results') (Join-Path $gateRoot 'tests/windows/results') -Recurse;New-Item -ItemType Directory -Path (Join-Path $gateRoot '.planning/phases/01-first-encrypted-drive-vertical-slice') -Force|Out-Null;Copy-Item (Join-Path $root '.planning/phases/01-first-encrypted-drive-vertical-slice/COVERAGE.md') (Join-Path $gateRoot '.planning/phases/01-first-encrypted-drive-vertical-slice/COVERAGE.md');$sourceClosure=Get-Content -Raw $manifest|ConvertFrom-Json;foreach($reference in @($sourceClosure.records|ForEach-Object {@($_.implementation_refs)+@($_.artifact_refs)})){$source=Join-Path $root ([string]$reference.path);$destination=Join-Path $gateRoot ([string]$reference.path);if(Test-Path -LiteralPath $source -PathType Leaf){New-Item -ItemType Directory -Path (Split-Path -Parent $destination) -Force|Out-Null;Copy-Item -LiteralPath $source -Destination $destination -Force}};$copiedClosure=Join-Path $gateRoot 'evidence/phase1/security-closure.yaml';$failedClosure=Get-Content -Raw $copiedClosure|ConvertFrom-Json;$latest=@($failedClosure.records[0].attestations)[-1];$signature=[string]$latest.signature_cms_base64;$replacement=if($signature[0]-eq'A'){'B'}else{'A'};$latest.signature_cms_base64=$replacement+$signature.Substring(1);[IO.File]::WriteAllText($copiedClosure,($failedClosure|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$failedGate=Invoke-FinalGate (Join-Path $gateRoot 'scripts/verify-phase1.ps1');Assert ($failedGate.Exit-ne0) 'canonical FinalGate propagates failing security subgate';Assert (($failedGate.Out+$failedGate.Err)-match'signature_invalid') ('FinalGate failure reports the security diagnostic: '+$failedGate.Out+' '+$failedGate.Err)}finally{Remove-Item $gateRoot -Recurse -Force -ErrorAction SilentlyContinue};$successfulGate=Invoke-FinalGate (Join-Path $root 'scripts/verify-phase1.ps1');Assert ($successfulGate.Exit-eq0) "canonical FinalGate succeeds: $($successfulGate.Out) $($successfulGate.Err)";Assert ($successfulGate.Out-match'verify-phase1: FinalGate PASSED') 'canonical FinalGate reports PASS';$manifestMatch=[regex]::Match($successfulGate.Out,'Security manifest digest\s*:\s*([a-f0-9]{64})');$policyMatch=[regex]::Match($successfulGate.Out,'Reviewer policy identity\s*:\s*([a-f0-9]{64})');Assert ($manifestMatch.Success-and$policyMatch.Success) 'FinalGate reports both security trust identities';$subgate=Invoke-Verify $manifest @('-RequireSignedOff','-TrustedRootPath',$env:PHASE1_TRUSTED_ROOT_PATH,'-ReviewerPolicyPath',$env:PHASE1_REVIEWER_POLICY_PATH);Assert ($subgate.Exit-eq0) 'security subgate succeeds beside FinalGate';$subgateResult=$subgate.Out|ConvertFrom-Json;Assert ($manifestMatch.Groups[1].Value-eq$subgateResult.manifest_digest-and$policyMatch.Groups[1].Value-eq$subgateResult.reviewer_policy_identity) 'FinalGate identities equal the successful security subgate'
}

if($Focus-eq'FinalGate'){Write-Host 'Phase 1 FinalGate propagation tests passed.';exit 0}

if($Focus-in@('All','Verifier')){
  if([string]::IsNullOrWhiteSpace($env:PHASE1_TRUSTED_ROOT_PATH)-or[string]::IsNullOrWhiteSpace($env:PHASE1_REVIEWER_POLICY_PATH)){throw 'phase1_reviewer_trust_setup_missing'};$realSignedOff=Invoke-Verify $manifest @('-RequireSignedOff','-TrustedRootPath',$env:PHASE1_TRUSTED_ROOT_PATH,'-ReviewerPolicyPath',$env:PHASE1_REVIEWER_POLICY_PATH);Assert ($realSignedOff.Exit-eq3) 'canonical manifest remains unsigned for the new archival-envelope generation until Plan 01-36 ceremony';$realSignedOffResult=$realSignedOff.Out|ConvertFrom-Json;Assert (@($realSignedOffResult.diagnostics|Where-Object code -eq 'historical_signature_envelope_missing').Count-eq19) 'every canonical record reports the missing archival envelope'
 $requiredEku='1.3.6.1.4.1.55555.1.34'
 $noUsage=New-VerifierTestCertificate -EkuOid $requiredEku;try{$fixture=New-VerifierFixture $noUsage $requiredEku;try{$result=Invoke-Verify $fixture.Closure @('-ThreatId',$fixture.Threat,'-RequireSignedOff','-TrustedRootPath',$fixture.Root,'-ReviewerPolicyPath',$fixture.Policy);Assert ($result.Exit-eq3) 'missing digital-signature usage is rejected';Assert (@(($result.Out|ConvertFrom-Json).diagnostics|Where-Object code -eq 'signer_key_usage_invalid').Count-eq1) 'missing key usage has stable diagnostic'}finally{Remove-Item $fixture.Directory -Recurse -Force}}finally{$noUsage.Dispose()}
 $noEku=New-VerifierTestCertificate -DigitalSignature;try{$fixture=New-VerifierFixture $noEku $requiredEku;try{$result=Invoke-Verify $fixture.Closure @('-ThreatId',$fixture.Threat,'-RequireSignedOff','-TrustedRootPath',$fixture.Root,'-ReviewerPolicyPath',$fixture.Policy);Assert ($result.Exit-eq3) 'missing policy EKU is rejected';Assert (@(($result.Out|ConvertFrom-Json).diagnostics|Where-Object code -eq 'signer_eku_invalid').Count-eq1) 'missing EKU has stable diagnostic'}finally{Remove-Item $fixture.Directory -Recurse -Force}}finally{$noEku.Dispose()}
  $validPurpose=New-VerifierTestCertificate -DigitalSignature -EkuOid $requiredEku;try{$fixture=New-VerifierFixture $validPurpose $requiredEku;try{$forgery=Get-Content -Raw $fixture.Closure|ConvertFrom-Json;$forgedRecord=@($forgery.records|Where-Object threat_id -eq $fixture.Threat)[0];$forgedAttestation=@($forgedRecord.attestations)[-1];$forgedAttestation.reviewer_identity.name='forged-reviewer';$forgedAttestation.attestation_digest=HashText (Body $forgedAttestation);[IO.File]::WriteAllText($fixture.Closure,($forgery|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$result=Invoke-Verify $fixture.Closure @('-ThreatId',$fixture.Threat,'-RequireSignedOff','-TrustedRootPath',$fixture.Root,'-ReviewerPolicyPath',$fixture.Policy);Assert ($result.Exit-eq3) 'recomputed valid-trust forgery is rejected';Assert (@(($result.Out|ConvertFrom-Json).diagnostics|Where-Object code -eq 'signature_invalid').Count-eq1) 'valid-trust forgery reaches CMS signature validation'}finally{Remove-Item $fixture.Directory -Recurse -Force}}finally{$validPurpose.Dispose()}
  $historyCert=New-VerifierTestCertificate -DigitalSignature -EkuOid $requiredEku;try{$fixture=New-VerifierFixture $historyCert $requiredEku;try{$valid=Invoke-Verify $fixture.Closure @('-ThreatId',$fixture.Threat,'-RequireSignedOff','-TrustedRootPath',$fixture.Root,'-ReviewerPolicyPath',$fixture.Policy);Assert ($valid.Exit-eq0) "trusted archival envelope passes: $($valid.Out) $($valid.Err)";foreach($mutation in @('byte','reorder','remove')){$tampered=Get-Content -Raw $fixture.Closure|ConvertFrom-Json;$record=@($tampered.records|Where-Object threat_id -eq $fixture.Threat)[0];if($mutation-eq'byte'){$signed=@($record.attestations|Where-Object {$_.PSObject.Properties['signature_cms_base64'] -and ![string]::IsNullOrWhiteSpace([string]$_.signature_cms_base64)});$raw=[Convert]::FromBase64String([string]$signed[0].signature_cms_base64);$raw[0]=$raw[0]-bxor1;$signed[0].signature_cms_base64=[Convert]::ToBase64String($raw)}elseif($mutation-eq'reorder'){$items=@($record.attestations);$record.attestations=@($items[1],$items[0])+@($items|Select-Object -Skip 2)}else{$record.attestations=@($record.attestations|Select-Object -Skip 1)};$candidate=Join-Path $fixture.Directory "$mutation.json";[IO.File]::WriteAllText($candidate,($tampered|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));$result=Invoke-Verify $candidate @('-ThreatId',$fixture.Threat,'-RequireSignedOff','-TrustedRootPath',$fixture.Root,'-ReviewerPolicyPath',$fixture.Policy);Assert ($result.Exit-eq3) "$mutation history tamper is rejected";Assert (@(($result.Out|ConvertFrom-Json).diagnostics|Where-Object code -eq 'historical_signature_digest_mismatch').Count-ge1) "$mutation history tamper has stable diagnostic"}}finally{Remove-Item $fixture.Directory -Recurse -Force}}finally{$historyCert.Dispose()}
 $referenceCases=@(
  @{Name='rooted';Path='C:\Windows\System32\drivers\etc\hosts';Error='reference_path_rooted'},
  @{Name='parent traversal';Path='..\outside-security-evidence.bin';Error='reference_path_outside'},
  @{Name='prefix collision';Path='..\dleakprevention-evil\evidence.bin';Error='reference_path_outside'},
  @{Name='mixed separator normalization';Path='scripts/..\..\outside-security-evidence.bin';Error='reference_path_outside'}
 )
  foreach($case in $referenceCases){$candidate=Mutate {param($c)$c.records[0].implementation_refs[0].path=$case.Path};try{$result=Invoke-Verify $candidate;Assert ($result.Exit-eq2) "$($case.Name) reference is rejected";$json=$result.Out|ConvertFrom-Json;Assert ($json.error-eq$case.Error) "$($case.Name) reference has stable containment diagnostic"}finally{Remove-Item $candidate -Force -ErrorAction SilentlyContinue}}
  $linkRoot=Join-Path $root ('.phase1-reparse-test-'+[guid]::NewGuid().ToString('N'));$externalRoot=Join-Path $env:TEMP ('phase1-reparse-external-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $linkRoot,$externalRoot|Out-Null;$externalFile=Join-Path $externalRoot 'outside.bin';[IO.File]::WriteAllText($externalFile,'outside-trust-boundary',[Text.UTF8Encoding]::new($false));$externalDigest=(FileHash $externalFile).ToLowerInvariant()
  try{
   $junction=Join-Path $linkRoot 'junction';New-Item -ItemType Junction -Path $junction -Target $externalRoot -ErrorAction Stop|Out-Null;$junctionRelative=RelativeToRoot (Join-Path $junction 'outside.bin');$candidate=Mutate {param($c)$c.records[0].implementation_refs[0].path=$junctionRelative;$c.records[0].implementation_refs[0].sha256=$externalDigest};try{$result=Invoke-Verify $candidate;Assert ($result.Exit-eq2) 'junction escape is rejected';Assert (($result.Out|ConvertFrom-Json).error-eq'reference_reparse_escape') 'junction escape has stable diagnostic'}finally{Remove-Item $candidate -Force -ErrorAction SilentlyContinue;try{[IO.Directory]::Delete($junction)}catch{}}
   $symlink=Join-Path $linkRoot 'outside-link.bin';New-Item -ItemType SymbolicLink -Path $symlink -Target $externalFile -ErrorAction Stop|Out-Null;$symlinkRelative=RelativeToRoot $symlink;$candidate=Mutate {param($c)$c.records[0].implementation_refs[0].path=$symlinkRelative;$c.records[0].implementation_refs[0].sha256=$externalDigest};try{$result=Invoke-Verify $candidate;Assert ($result.Exit-eq2) 'symbolic-link escape is rejected';Assert (($result.Out|ConvertFrom-Json).error-eq'reference_reparse_escape') 'symbolic-link escape has stable diagnostic'}finally{Remove-Item $candidate -Force -ErrorAction SilentlyContinue;try{[IO.File]::Delete($symlink)}catch{}}
  }finally{Remove-Item $externalFile -Force -ErrorAction SilentlyContinue;try{[IO.Directory]::Delete($externalRoot)}catch{};try{[IO.Directory]::Delete($linkRoot)}catch{}}
 }

$base=Invoke-Verify $manifest;Assert ($base.Exit-eq0) 'canonical pre-sign-off validation'
$missing=Invoke-Verify $manifest @('-RequireSignedOff');Assert ($missing.Exit-eq2) 'signed-off mode requires external trust inputs';Assert (($missing.Out|ConvertFrom-Json).error-eq'trusted_root_missing') 'stable missing-root diagnostic'
$fakeRoot=Join-Path $env:TEMP("root-$([guid]::NewGuid()).cer");$fakePolicy=Join-Path $env:TEMP("policy-$([guid]::NewGuid()).json");[IO.File]::WriteAllText($fakeRoot,'manifest copied trust cannot substitute',[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($fakePolicy,'{}',[Text.UTF8Encoding]::new($false));try{$bad=Invoke-Verify $manifest @('-RequireSignedOff','-TrustedRootPath',$fakeRoot,'-ReviewerPolicyPath',$fakePolicy);Assert ($bad.Exit-eq2) 'malformed external trust inputs fail closed'}finally{Remove-Item $fakeRoot,$fakePolicy -Force}

# Fully recompute attacker-controlled hashes after forging reviewer provenance. A detached signature cannot be recomputed.
$forged=Mutate {param($c)$r=$c.records[0];$r.attestations[0].reviewer_identity.name='forged\reviewer';$prior='';foreach($a in @($r.attestations)){$a.previous_attestation_digest=$prior;$a.attestation_digest=HashText (Body $a);$prior=$a.attestation_digest}}
try{$fakeRoot=Join-Path $env:TEMP("root-$([guid]::NewGuid()).cer");$fakePolicy=Join-Path $env:TEMP("policy-$([guid]::NewGuid()).json");[IO.File]::WriteAllText($fakeRoot,'x');[IO.File]::WriteAllText($fakePolicy,'{}');$forgedResult=Invoke-Verify $forged @('-RequireSignedOff','-TrustedRootPath',$fakeRoot,'-ReviewerPolicyPath',$fakePolicy);Assert ($forgedResult.Exit-ne0) 'recomputed forgery rejected'}finally{Remove-Item $forged,$fakeRoot,$fakePolicy -Force -ErrorAction SilentlyContinue}

$verifierSource=Get-Content -Raw $verifier;$finalSource=Get-Content -Raw (Join-Path $root 'scripts/verify-phase1.ps1')
Assert ($verifierSource-match'SignedCms' -and $verifierSource-match'CheckSignature') 'detached CMS verification is wired'
Assert ($verifierSource-match'Add-Type\s+-AssemblyName\s+System\.Security' -and $verifierSource-match'pkcs_runtime_unavailable') 'verifier loads PKCS runtime explicitly with a distinct failure diagnostic'
Assert ($finalSource-match'TrustedRootPath' -and $finalSource-match'ReviewerPolicyPath' -and $finalSource-match'RequireSignedOff') 'FinalGate forwards authenticated trust inputs'
Assert ($finalSource-match'manifest_digest' -and $finalSource-match'reviewer_policy_identity') 'FinalGate reports matching identities'

# Capture must display every protected field and cannot bypass affirmative review with a switch.
$captureSource=Get-Content -Raw $capture
foreach($field in @('threat_id','disposition','severity','mitigation_assertion','implementation_refs','evidence_attempt_ids','required_machine_roles','artifact_refs','procedure_version','environment_fingerprint')){Assert ($captureSource-match[regex]::Escape($field)) "capture protects field $field"}
Assert ($captureSource-notmatch'ConfirmEach') 'optional confirmation bypass removed'
Assert ($captureSource-match'Read-Host' -and $captureSource-match"-ne\s*'YES'") 'exact affirmative input required'
Assert ($captureSource-match'SignedCms' -and $captureSource-match'ComputeSignature') 'reviewer-controlled CMS signing wired'
Assert ($captureSource-match'Add-Type\s+-AssemblyName\s+System\.Security' -and $captureSource-match'pkcs_runtime_unavailable') 'capture loads PKCS runtime explicitly and fails closed when unavailable'

$tmp=Join-Path $env:TEMP("closure-$([guid]::NewGuid()).json");Copy-Item $manifest $tmp;try{$before=FileHash $tmp;&powershell -NoProfile -ExecutionPolicy Bypass -File $capture -ClosurePath $tmp -ThreatId T-01-15-03 -DryRun;$exit=$LASTEXITCODE;Assert ($exit-eq0) 'dry run succeeds';Assert ((FileHash $tmp)-eq$before) 'dry run byte-identical';&powershell -NoProfile -ExecutionPolicy Bypass -File $capture -ClosurePath $tmp -ThreatId T-01-15-03 -WhatIf 2>$null;Assert ((FileHash $tmp)-eq$before) 'WhatIf byte-identical'}finally{Remove-Item $tmp -Force}

# Publication source contract: named cross-process mutex, locked re-read, flush-through, atomic replace, and test hooks.
foreach($needle in @('Mutex','PublicationBarrierPath','CrashBeforeReplace','Flush($true)','Replace(')){Assert ($captureSource-match[regex]::Escape($needle)) "publication contract includes $needle"}
Assert ($captureSource-match'Get-PublicationMutexName' -and $captureSource-match'WaitOne') 'all publishers serialize on the canonical manifest path'
Write-Host 'Phase 1 security closure tests passed.'
